import{_ as a,o as t,c as o,ag as i}from"./chunks/framework.D5hoimZQ.js";const g=JSON.parse('{"title":"科学日报 · 2026-10-08（材料科学）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/materials/science-daily-2026-10-08.md","filePath":"topics/materials/science-daily-2026-10-08.md"}'),r={name:"topics/materials/science-daily-2026-10-08.md"};function l(s,e,c,n,d,p){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="科学日报-·-2026-10-08-材料科学" tabindex="-1">科学日报 · 2026-10-08（材料科学） <a class="header-anchor" href="#科学日报-·-2026-10-08-材料科学" aria-label="Permalink to &quot;科学日报 · 2026-10-08（材料科学）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-08.md</code> — 第31期</p></blockquote><hr><h2 id="带隙突破-7-ev-的硅掺杂-α-alxga1−x-2o3-半导体-nature" tabindex="-1">带隙突破 7 eV 的硅掺杂 α-(AlₓGa₁₋ₓ)₂O₃ 半导体（Nature） <a class="header-anchor" href="#带隙突破-7-ev-的硅掺杂-α-alxga1−x-2o3-半导体-nature" aria-label="Permalink to &quot;带隙突破 7 eV 的硅掺杂 α-(AlₓGa₁₋ₓ)₂O₃ 半导体（Nature）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-08.md</code> ｜ DOI: 10.1038/s41586-026-11085-3</p></blockquote><ul><li>背景：功率电子中带隙越宽效率与功率密度越高（<strong>Baliga 优值 ∝ Eg^5.5</strong>），但带隙越大越难用<strong>平衡掺杂</strong>把电导率可控地调制几个数量级——这是超宽带隙半导体的核心瓶颈。</li><li>方法：用<strong>亚氧化物分子束外延</strong>生长硅掺杂的 α-(AlₓGa₁₋ₓ)₂O₃ 薄膜。</li><li>数据：带隙 <strong>&gt; 7.0 eV</strong>，<strong>超过立方氮化硼</strong>；在 &gt;6 eV 的&quot;巨大带隙&quot;区间，室温电导率比以往同类材料<strong>高出逾一亿倍</strong>。</li><li>洞察：延续本库材料主线（钯膜电化学脱氢、深泡沫光刻）——<strong>当旧约束成为瓶颈，答案常常不是把旧机制调更优，而是换合成窗口/受力维度</strong>；大带隙未必等于不可控导电。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/materials/index.md</code> ｜ 第31期 科学板块</p></blockquote><p>关键词：超宽带隙半导体、α-(AlGa)₂O₃、亚氧化物分子束外延、硅掺杂、Baliga 优值、功率电子、立方氮化硼 关联：<code>topics/materials/2026-q3-breakthroughs.md</code>（Q3 材料突破合集）、<code>topics/materials/science-daily-2026-09-15.md</code>（钯膜脱氢：换维度突破旧约束的同一母题）</p>',9)])])}const m=a(r,[["render",l]]);export{g as __pageData,m as default};
